-- Base inicial para MySQL 8+ na hospedagem. Não contém senhas ou dados reais.
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','tecnico','financeiro') NOT NULL DEFAULT 'tecnico', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, document VARCHAR(18), phone VARCHAR(30), email VARCHAR(120), address VARCHAR(200), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE service_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, number INT UNSIGNED NOT NULL UNIQUE, client_id BIGINT UNSIGNED NOT NULL, type ENUM('Ordem de Serviço','Orçamento') NOT NULL DEFAULT 'Ordem de Serviço', status ENUM('Aberta','Em andamento','Aguardando aprovação','Concluída') NOT NULL DEFAULT 'Aberta', service_date DATE NOT NULL, description TEXT NOT NULL, notes TEXT, amount DECIMAL(12,2) NOT NULL DEFAULT 0, photo_path VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_orders_client FOREIGN KEY (client_id) REFERENCES clients(id));
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, description VARCHAR(500), reference_price DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE tools (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, asset_code VARCHAR(60), status ENUM('Disponível','Em uso','Em manutenção') NOT NULL DEFAULT 'Disponível', notes VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE financial_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, description VARCHAR(150) NOT NULL, amount DECIMAL(12,2) NOT NULL, due_date DATE NOT NULL, status ENUM('Em aberto','Paga') NOT NULL DEFAULT 'Em aberto', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
